import React from 'react';
import {AbsoluteFill, random} from 'remotion';
import {SANS} from './treatments/common';

// The cover of a blog post (NAV-139), drawn here and rendered as a still PNG: dev.to 1000x420, LinkedIn 1200x627. The title, a kicker, a few keyword chips, a palette and a motif chosen for the post's idea.
// The palette and motif names are mirrored in scripts/blog_images.py (a test keeps the lists equal). Only words and shapes: nothing here is generated by a model, so the text is always right.

export type CoverProps = {width: number; height: number; title: string; kicker: string; chips: string[]; palette: string; motif: string; seed: string; brand: string};
export const coverDefaults: CoverProps = {width: 1000, height: 420, title: 'Why confident answers are not evidence', kicker: 'AI engineering', chips: ['agents', 'evals', 'trust'], palette: 'midnight', motif: 'nodes', seed: 'blog-001', brand: 'NAVAAN'};

type Pal = {a: string; b: string; ink: string; mute: string; accent: string; shape: string};
export const PALETTES: Record<string, Pal> = {
  midnight: {a: '#0B1020', b: '#1B2A4A', ink: '#F4F7FF', mute: '#AEB9D3', accent: '#E2B75A', shape: '#E2B75A'},
  indigo: {a: '#1A1446', b: '#3B2FA0', ink: '#F5F3FF', mute: '#C4BEF2', accent: '#9FB4FF', shape: '#9FB4FF'},
  forest: {a: '#0E2A22', b: '#1E5B45', ink: '#F0FBF5', mute: '#A9D4C0', accent: '#7BE0AD', shape: '#7BE0AD'},
  ember: {a: '#2A1210', b: '#7A2E1E', ink: '#FFF6EF', mute: '#E7BFAE', accent: '#FFB86B', shape: '#FFB86B'},
  ocean: {a: '#082433', b: '#0E6C8A', ink: '#EEFBFF', mute: '#A6D9E6', accent: '#7FE5F0', shape: '#7FE5F0'},
  slate: {a: '#1E2329', b: '#3A434D', ink: '#F5F7FA', mute: '#B6BEC8', accent: '#F2C14E', shape: '#F2C14E'},
  paper: {a: '#F5F1E8', b: '#E7DFCE', ink: '#1F2328', mute: '#5E5A50', accent: '#B4472A', shape: '#B4472A'},
  mono: {a: '#0A0A0A', b: '#262626', ink: '#FFFFFF', mute: '#B5B5B5', accent: '#FFFFFF', shape: '#FFFFFF'},
};
export const MOTIFS = ['nodes', 'grid', 'waves', 'rings', 'blocks', 'stripes', 'none'];

const Motif: React.FC<{kind: string; seed: string; w: number; h: number; pal: Pal}> = ({kind, seed, w, h, pal}) => {
  const r = (k: string) => random(`${seed}-${kind}-${k}`);
  const sw = Math.max(2, Math.round(h / 140)), c = pal.shape;
  if (kind === 'nodes') {
    const pts = Array.from({length: 11}, (_, i) => ({x: 0.1 * w + r(`x${i}`) * 0.8 * w, y: 0.1 * h + r(`y${i}`) * 0.8 * h, s: 0.5 + r(`s${i}`)}));
    return <svg width={w} height={h}>{pts.flatMap((p, i) => pts.slice(i + 1).filter((q) => Math.hypot(p.x - q.x, p.y - q.y) < 0.42 * w).map((q, j) => <line key={`${i}-${j}`} x1={p.x} y1={p.y} x2={q.x} y2={q.y} stroke={c} strokeOpacity={0.35} strokeWidth={sw} />))}
      {pts.map((p, i) => <circle key={i} cx={p.x} cy={p.y} r={(i % 4 === 0 ? 0.022 : 0.016) * h * 2 * p.s} fill={i % 4 === 0 ? c : 'none'} stroke={c} strokeWidth={sw} strokeOpacity={0.9} />)}</svg>;
  }
  if (kind === 'grid') {
    const cols = 9, rows = 6, gx = w / (cols + 1), gy = h / (rows + 1);
    return <svg width={w} height={h}>{Array.from({length: cols * rows}, (_, i) => { const x = ((i % cols) + 1) * gx, y = (Math.floor(i / cols) + 1) * gy, on = r(`g${i}`) > 0.72; return on ? <rect key={i} x={x - gx * 0.3} y={y - gy * 0.3} width={gx * 0.6} height={gy * 0.6} rx={gy * 0.12} fill={c} fillOpacity={0.9} /> : <circle key={i} cx={x} cy={y} r={sw * 1.3} fill={c} fillOpacity={0.45} />; })}</svg>;
  }
  if (kind === 'waves') {
    return <svg width={w} height={h}>{Array.from({length: 7}, (_, k) => { const amp = (0.05 + 0.05 * r(`a${k}`)) * h, ph = r(`p${k}`) * 6, y0 = (0.18 + k * 0.11) * h; const d = Array.from({length: 41}, (_, i) => `${i ? 'L' : 'M'}${(i / 40) * w} ${y0 + Math.sin(i / 40 * 9 + ph) * amp}`).join(' '); return <path key={k} d={d} fill="none" stroke={c} strokeWidth={sw * (k === 3 ? 2 : 1)} strokeOpacity={k === 3 ? 0.95 : 0.35} strokeLinecap="round" />; })}</svg>;
  }
  if (kind === 'rings') {
    return <svg width={w} height={h}>{Array.from({length: 6}, (_, k) => <circle key={k} cx={w * 0.55} cy={h * 0.5} r={(0.12 + k * 0.09) * Math.min(w, h * 1.6)} fill="none" stroke={c} strokeWidth={sw * (k === 2 ? 2.4 : 1)} strokeOpacity={k === 2 ? 0.95 : 0.3} strokeDasharray={k % 2 ? `${sw * 4} ${sw * 5}` : undefined} />)}<circle cx={w * 0.55} cy={h * 0.5} r={h * 0.045} fill={c} /></svg>;
  }
  if (kind === 'blocks') {
    return <svg width={w} height={h}>{Array.from({length: 7}, (_, i) => { const bw = (0.3 + 0.55 * r(`w${i}`)) * w, bh = h * 0.085; return <rect key={i} x={w - bw - 0.04 * w} y={0.12 * h + i * h * 0.115} width={bw} height={bh} rx={bh / 2} fill={c} fillOpacity={i === 2 ? 0.95 : 0.22 + 0.25 * r(`o${i}`)} />; })}</svg>;
  }
  if (kind === 'stripes') {
    return <svg width={w} height={h}>{Array.from({length: 9}, (_, i) => <polygon key={i} points={`${w * (0.1 + i * 0.1)},0 ${w * (0.1 + i * 0.1) + w * 0.05},0 ${w * (0.1 + i * 0.1) - w * 0.25 + w * 0.05},${h} ${w * (0.1 + i * 0.1) - w * 0.25},${h}`} fill={c} fillOpacity={i === 4 ? 0.9 : 0.14 + 0.1 * r(`s${i}`)} />)}</svg>;
  }
  return null;
};

export const BlogCover: React.FC<CoverProps> = (p) => {
  const pal = PALETTES[p.palette] ?? PALETTES.midnight, w = p.width, h = p.height, pad = Math.round(h * 0.13), textW = Math.round(w * 0.54);
  // the title's size: the largest at which its words, wrapped in the column, fit the room between the kicker and the chips (about 0.5 of the height)
  const n = Array.from(p.title).length, room = h * 0.5;
  let base = h * 0.07; for (let sz = h * 0.2; sz >= h * 0.07; sz -= h * 0.004) { const lines = Math.ceil((n * sz * 0.56 * 1.1) / textW); if (lines * sz * 1.08 <= room) { base = sz; break; } }
  return (
    <AbsoluteFill style={{background: `linear-gradient(135deg, ${pal.a} 0%, ${pal.b} 100%)`, fontFamily: SANS, overflow: 'hidden'}}>
      <div style={{position: 'absolute', right: 0, top: 0, width: w * 0.44, height: h}}><Motif kind={p.motif} seed={p.seed} w={w * 0.44} h={h} pal={pal} /></div>
      <div style={{position: 'absolute', left: pad, top: pad, bottom: pad, width: textW, display: 'flex', flexDirection: 'column', justifyContent: 'space-between'}}>
        <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: h * 0.04}}>
          <span style={{fontSize: h * 0.05, letterSpacing: h * 0.011, textTransform: 'uppercase', fontWeight: 800, color: pal.accent}}>{p.kicker}</span>
          {p.brand ? <span style={{fontSize: h * 0.04, letterSpacing: h * 0.008, fontWeight: 700, color: pal.mute, textTransform: 'uppercase'}}>{p.brand}</span> : null}   {/* no brand mark by default: a blog image carries the post, not NAVAAN's name (NAV-148) */}
        </div>
        <div style={{fontSize: base, lineHeight: 1.06, fontWeight: 800, letterSpacing: -base * 0.02, color: pal.ink, overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 4, WebkitBoxOrient: 'vertical'}}>{p.title}</div>
        <div style={{display: 'flex', alignItems: 'center', gap: h * 0.03, flexWrap: 'wrap'}}>
          <div style={{width: h * 0.1, height: h * 0.018, borderRadius: h * 0.01, background: pal.accent}} />
          {p.chips.slice(0, 4).map((c, i) => <span key={i} style={{fontSize: h * 0.047, fontWeight: 700, color: pal.ink, border: `${Math.max(1, h * 0.005)}px solid ${pal.mute}`, borderRadius: 999, padding: `${h * 0.012}px ${h * 0.035}px`}}>{c}</span>)}
        </div>
      </div>
    </AbsoluteFill>
  );
};
